import{z as n,x as i,o as t,c as p,q as B,j as l,D as E,d as r,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const V=JSON.parse('{"title":"缺页路径","description":"","frontmatter":{"title":"缺页路径","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/page-fault-path.md","filePath":"cs/page-fault-path.md","lastUpdated":1791063341000}'),d={name:"cs/page-fault-path.md"};function m(h,a,c,D,C,u){const A=i("Mermaid");return t(),p("div",null,[a[2]||(a[2]=B('<h1 id="缺页路径" tabindex="-1">缺页路径 <a class="header-anchor" href="#缺页路径" aria-label="Permalink to &quot;缺页路径&quot;">​</a></h1><div class="epigraph"><p>缺页陷入之后，内核要判断：非法、补页、写时复制，还是发给进程一个信号。</p><footer>—— 据 Silberschatz et al., Operating System Concepts；Love, Linux Kernel Development 整理</footer></div><p><a href="/cs/demand-paging">上一课</a>给出策略：合法访问可以在触及才占帧。<a href="/cs/paging-vm">分页</a>的缺页异常已经能进内核，本课不重导页表。<a href="/cs/brk-heap">brk 与堆</a>只保证区间合法。缺口是<strong>路径</strong>：硬件向量之后，内核如何找到那一段 VMA，并决定 minor/major、杀进程或重试指令。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一类「页表项无效」至少有三种前途：地址不在任何 VMA（野指针）；在 VMA 里但还没有帧（按需）；在 VMA 里且有帧但不能写（保护或后课 COW）。若缺页处理把三者混成一种「再配一页」，只读文本会被写成可写。缺口不是 TLB 怎么查，而是：取故障地址 → 查进程的虚区间树 → 对照错误码里的写/用户/指令位 → 分配或拒绝。</p><p>本课不把每种架构的 error code 位图背完。</p><p><span class="marginnote">minor 缺页：页已在内存（如页 Cache），只需填表。major：要读磁盘或 swap。会计进进程的缺页计数，调度与后课抖动会用到。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>入口沿用组成课的精确异常：保存 trapframe，内核用故障 VA 查 VMA。无 VMA 或权限不够：投递 <code>SIGSEGV</code>（后课信号），不配帧。有 VMA：按需分配帧、必要时从文件读入、置权限、冲本 CPU 的 <a href="/cs/tlb-translate">TLB</a>，返回用户重试。栈守卫页可触发一次扩展，仍须受上限约束。</p><p><span class="marginnote">VMA（虚拟内存区间）可以翻译成进程地址空间的「户口本」：每一段虚拟地址都登记了起点、终点和读写权限。缺页时内核拿故障地址逐段对号入座，查不到户口就定性为野指针——SIGSEGV 就是这么来的。</span></p>',10)),(t(),l(s,null,{default:E(()=>[o(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAULT%5B%22%E7%BC%BA%E9%A1%B5%E9%99%B7%E5%85%A5%22%5D%20--%3E%20VMA%5B%22%E6%9F%A5%20VMA%22%5D%0A%20%20VMA%20--%3E%20BAD%5B%22%E6%97%A0%E5%8C%BA%E9%97%B4%E6%88%96%E8%B6%8A%E6%9D%83%3A%20%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20VMA%20--%3E%20FILL%5B%22%E5%90%88%E6%B3%95%3A%20%E9%85%8D%E5%B8%A7%E6%88%96%E5%A1%AB%20Cache%22%5D%0A%20%20FILL%20--%3E%20RETRY%5B%22%E8%BF%94%E5%9B%9E%E9%87%8D%E8%AF%95%E6%8C%87%E4%BB%A4%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"路径把「按需」从口号收成可审计的分支：文件页走 inode 与后课页 Cache；匿名页填零。内核自己的缺页（例如拷贝用户缓冲时）不能杀内核，只能把错误返回给系统调用。这与用户指令缺页同走 MMU，处理函数不同。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"匿名页就是不挂任何文件的后备内存，比如 malloc 出来的堆。给它配 4 KB 帧后要整页清零——4 KB 就是 4096 字节，相当于把这一页 4096 个位置全写成 0；不清零的话，进程会读到上一个进程遗留的旧数据，就是典型的信息泄露隐患。")],-1)),a[6]||(a[6]=e("p",null,"合法地址确定要补页后，第一道分岔是「这一页现在到底在不在内存」：在页 Cache 里就只需填表，不在才动磁盘。",-1)),(t(),l(s,null,{default:E(()=>[o(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%90%88%E6%B3%95%E7%BC%BA%E9%A1%B5%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20B%7B%22%E9%A1%B5%E5%B7%B2%E5%9C%A8%E9%A1%B5%20Cache%3F%22%7D%0A%20%20B%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20C%5B%22minor%3A%20%E5%8F%AA%E5%A1%AB%E9%A1%B5%E8%A1%A8%E9%A1%B9%22%5D%0A%20%20B%20--%3E%7C%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%7C%20D%7B%22%E6%96%87%E4%BB%B6%E9%A1%B5%E8%BF%98%E6%98%AF%E5%8C%BF%E5%90%8D%E9%A1%B5%3F%22%7D%0A%20%20D%20--%3E%7C%22%E6%96%87%E4%BB%B6%E9%A1%B5%22%7C%20F%5B%22major%3A%20%E4%BB%8E%E7%A3%81%E7%9B%98%E8%AF%BB%E5%85%A5%E5%B8%A7%22%5D%0A%20%20D%20--%3E%7C%22%E5%8C%BF%E5%90%8D%E9%A1%B5%22%7C%20E%5B%22%E9%85%8D%E5%B8%A7%E5%B9%B6%E6%95%B4%E9%A1%B5%E5%A1%AB%E9%9B%B6%22%5D%0A%20%20C%20--%3E%20G%5B%22%E7%BD%AE%E6%9D%83%E9%99%90%20%E5%86%B2%20TLB%20%E9%87%8D%E8%AF%95%22%5D%0A%20%20E%20--%3E%20G%0A%20%20F%20--%3E%20G%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<p>不要在这里重写多级页表 walker：那是分页课与 TLB 课的对象。本课只使用「硬件已经指出 VA 与错误类型」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>userfaultfd</code> 把缺页交给用户态处理的全部协议。不把 NUMA 的远程帧分配写成默认。指令与数据缺页在统计上可分开，教学上同一条路径。多核上改页表之后其他 CPU 的 TLB 仍可能是旧的，那是后课 shootdown。</p><p>后课默认：缺页已能对 4K 页正确补表。TLB 压力与页表层数，下一课用大页来减。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>缺页先对 VMA 与权限分类，再配帧或发信号。</li><li>minor/major 区分「是否访盘」，不改页表格式。</li><li>大页如何减少翻译项，是下一课。</li><li>出处：Silberschatz et al., <em>OSC</em>；Love, <em>LKD</em>；Tanenbaum <em>MOS</em>。</li></ul><p><span class="marginnote">常见误区：段错误不是编译器在编译期查出来的。编译器照样放行野指针，要等到 CPU 访问那一刻触发缺页、内核查 VMA 查不到，才由内核投递 SIGSEGV。这也解释了为什么同一段坏代码有时崩有时不崩——取决于那块地址当时碰巧有没有被映射。</span></p>',7))])}const T=n(d,[["render",m]]);export{V as __pageData,T as default};
